--- a/src/pricing/discount.js
+++ b/src/pricing/discount.js
@@ -1,13 +1,81 @@
 /**
- * INCOMPLETE — implement applyDiscounts(lines, coupons).
- * Rules (acceptance tests encode these):
+ * applyDiscounts(lines, coupons)
  * - coupons: { code, type: "percent"|"fixed", value, stackable?: boolean }
- * - percent applies to subtotal of matching lines before tax
+ * - percent applies to current subtotal before tax
  * - fixed subtracts cents from subtotal (floor at 0)
  * - non-stackable coupons: only the single best discount (max savings) applies
  * - stackable coupons combine after the best non-stackable (if any)
  * - never increase price; clamp subtotal >= 0
  */
-export function applyDiscounts(_lines, _coupons) {
-  throw new Error("NOT_IMPLEMENTED:applyDiscounts");
+
+function baseSubtotal(lines) {
+  return lines.reduce((sum, line) => sum + line.line_subtotal_cents, 0);
+}
+
+function savingsFor(coupon, subtotal) {
+  if (subtotal <= 0) return 0;
+  if (coupon.type === "percent") {
+    return Math.min(subtotal, Math.round((subtotal * coupon.value) / 100));
+  }
+  if (coupon.type === "fixed") {
+    return Math.min(subtotal, coupon.value);
+  }
+  return 0;
+}
+
+function scaleLines(lines, fromSubtotal, toSubtotal) {
+  if (fromSubtotal <= 0) {
+    return lines.map((line) => ({ ...line, line_subtotal_cents: 0 }));
+  }
+  if (toSubtotal >= fromSubtotal) {
+    return lines.map((line) => ({ ...line }));
+  }
+  const scaled = lines.map((line) => ({
+    ...line,
+    line_subtotal_cents: Math.round((line.line_subtotal_cents * toSubtotal) / fromSubtotal),
+  }));
+  const drift = toSubtotal - scaled.reduce((sum, line) => sum + line.line_subtotal_cents, 0);
+  if (drift !== 0 && scaled.length > 0) {
+    scaled[0] = {
+      ...scaled[0],
+      line_subtotal_cents: Math.max(0, scaled[0].line_subtotal_cents + drift),
+    };
+  }
+  return scaled;
+}
+
+export function applyDiscounts(lines, coupons = []) {
+  const original = baseSubtotal(lines);
+  let subtotal = original;
+  const applied = [];
+  const list = Array.isArray(coupons) ? coupons : [];
+  const nonStackable = list.filter((c) => !c.stackable);
+  const stackable = list.filter((c) => c.stackable);
+
+  if (nonStackable.length > 0) {
+    let best = nonStackable[0];
+    let bestSavings = savingsFor(best, subtotal);
+    for (let i = 1; i < nonStackable.length; i++) {
+      const coupon = nonStackable[i];
+      const savings = savingsFor(coupon, subtotal);
+      if (savings > bestSavings) {
+        best = coupon;
+        bestSavings = savings;
+      }
+    }
+    subtotal = Math.max(0, subtotal - bestSavings);
+    applied.push(best.code);
+  }
+
+  for (const coupon of stackable) {
+    const savings = savingsFor(coupon, subtotal);
+    subtotal = Math.max(0, subtotal - savings);
+    applied.push(coupon.code);
+  }
+
+  return {
+    subtotal_cents: Math.max(0, subtotal),
+    applied,
+    lines: scaleLines(lines, original, Math.max(0, subtotal)),
+  };
 }
